var numOfSubarrays = function(arr) {
    const MOD = 10 ** 9 + 7;
    let count = 0;
    let prefixSum = 0;
    let oddCount = 0;
    let evenCount = 1;

    for (const num of arr) {
        prefixSum += num;

        if (prefixSum % 2 === 0) {
            count += oddCount;
            evenCount++;
        } else {
            count += evenCount;
            oddCount++;
        }

        count %= MOD;
    }

    return count;
};

